import{_ as o,o as i,c as n,a2 as a}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0038 — Retention delle revisioni, compattazione del changelog e copie di conflitto","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0038-retention-e-finestra-changelog.md","filePath":"adr/0038-retention-e-finestra-changelog.md"}'),t={name:"adr/0038-retention-e-finestra-changelog.md"};function c(l,e,r,s,d,g){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0038-—-retention-delle-revisioni-compattazione-del-changelog-e-copie-di-conflitto" tabindex="-1">ADR-0038 — Retention delle revisioni, compattazione del changelog e copie di conflitto <a class="header-anchor" href="#adr-0038-—-retention-delle-revisioni-compattazione-del-changelog-e-copie-di-conflitto" aria-label="Permalink to &quot;ADR-0038 — Retention delle revisioni, compattazione del changelog e copie di conflitto&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §2.6.2, §2.6.3, §3.2.2, §3.4.4 B, C.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.2 (storico e retention), §3.2.2 (DDL <code>file_revisions</code>), §3.4 (protocollo di sync, <code>CURSOR_EXPIRED</code>); D-03, D-04; ADR-0009, ADR-0033</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì: §3.2.2 (DDL) e la descrizione della finestra del changelog in §3.4 vanno aggiornate come in questo ADR</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;analisi del 2026-11-01 ha trovato tre difetti nel job di retention del cloud (<code>internal/revisions</code>, <code>internal/jobs</code>), tutti verificati con test d&#39;integrazione:</p><ol><li><strong>Retention bloccata dalle copie di conflitto.</strong> <code>file_revisions.conflict_of</code> puntava alla revisione dell&#39;originale senza <code>ON DELETE</code>. Quella revisione, una volta diventata non corrente e più vecchia di <code>history.retention_days</code>, era scelta per la cancellazione: il vincolo falliva (23503), l&#39;intero batch tornava indietro e ogni esecuzione successiva ripartiva dalle stesse righe. La retention si fermava per tutta l&#39;installazione.</li><li><strong>Buchi nel changelog.</strong> La retention (30 giorni, poi una revisione al giorno fino a 90) cancella revisioni che la finestra del changelog (<code>sync.changelog_window_days</code>, 90 giorni) serve ancora. L&#39;unico controllo di completezza di <code>changes?since</code> è <code>since &lt; compaction_seq</code>, che la retention non spostava. Un client fermo da più di 30 giorni riceveva quindi un changelog con dei salti: per esempio la modifica successiva a uno spostamento cancellato, che riscriveva il file al vecchio percorso. Le repliche divergevano senza alcun segnale (contro D-04).</li><li><strong>Paginazione.</strong> La scansione dei candidati non aveva cursore e si fermava alla prima pagina senza nulla da cancellare: con più di 5000 &quot;sopravvissuti giornalieri&quot; in testa, i file successivi non venivano mai potati.</li></ol><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><strong>Copie di conflitto:</strong> <code>conflict_of</code> diventa <code>ON DELETE SET NULL</code> con un indice parziale. La nuova colonna <code>conflict_of_file</code> (id del file originale, scritta al commit e riempita per le righe esistenti) è ciò che il changelog restituisce come <code>conflict_of</code>. La risposta API non cambia e non dipende più dalla sopravvivenza della revisione referenziata. Migrazione <code>0007_retention_fixes.sql</code>.</li><li><strong>Compattazione legata alla retention:</strong> nella stessa transazione del prune, per ogni vault <code>compaction_seq</code> avanza fino al <code>seq</code> più alto tra le revisioni cancellate con operazione <strong>diversa da <code>modify</code></strong> (create, move, delete, restore), tramite <code>vaults.AdvanceCompaction</code> (ADR-0033). <ul><li>Le <code>modify</code> superate si possono perdere senza danno: una revisione successiva dello stesso file ha un <code>seq</code> più alto e porta il contenuto aggiornato.</li><li>Un cursore precedente a un&#39;operazione strutturale cancellata riceve <code>CURSOR_EXPIRED</code> e il client esegue il bootstrap, invece di applicare un changelog incompleto.</li></ul></li><li><strong>Paginazione keyset</strong> su <code>(file_id, server_time, id)</code>, con indice dedicato. L&#39;ultima riga di ogni pagina serve solo da look-ahead e si decide nella pagina successiva, così la regola &quot;ultima revisione del giorno&quot; vale anche tra una pagina e l&#39;altra.</li><li><strong>Indici:</strong> <code>files_blob_ix</code> (controllo d&#39;integrità del GC dei blob), rimozione di <code>file_revisions_changes_ix</code> (duplicato dell&#39;indice di <code>UNIQUE (vault_id, seq)</code>).</li><li><strong>Riconciliazione dei contatori</strong> (<code>ReconcileUsage</code>, <code>ReconcileBlobRefs</code>): ogni correzione blocca la riga (<code>FOR UPDATE</code>), ricalcola il valore e scrive solo se differisce. Non si scrive più un valore preso da uno snapshot precedente.</li><li><strong>Scheduler dei job:</strong> gli advisory lock usano un piccolo pool dedicato, così un job non tiene occupata una connessione del pool principale mentre ne chiede un&#39;altra. Le prime esecuzioni sono scaglionate e il pool principale ha un minimo di 8 connessioni se <code>DATABASE_URL</code> non specifica <code>pool_max_conns</code>.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Non potare le revisioni non-<code>modify</code> dentro la finestra del changelog:</strong> la finestra di 90 giorni resterebbe completa, ma la retention dello storico (§2.6.2) avrebbe un&#39;eccezione difficile da spiegare e lo storico conterebbe righe che l&#39;utente non vede. Scartata.</li><li><strong>Portare la retention a 90 giorni:</strong> più storico fuori quota (D-03) e un costo di storage per tutte le installazioni, solo per servire client fermi a lungo. Scartata.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Finestra effettiva più corta:</strong> per un client che resta indietro oltre una create, move, delete o restore già potata, la finestra effettiva del changelog si riduce da <code>sync.changelog_window_days</code> a circa <code>history.retention_days</code>. Ne segue un bootstrap, che è sicuro: nessun file locale viene cestinato senza prova. È il prezzo di non servire mai un changelog con dei salti.</li><li><strong>Lo spec va aggiornato:</strong> il DDL di §3.2.2 (<code>conflict_of ... ON DELETE SET NULL</code>, colonna <code>conflict_of_file</code>, nuovi indici, nessun <code>file_revisions_changes_ix</code>) e la descrizione della finestra del changelog in §3.4.</li><li><strong>Migrazione:</strong> gli indici della 0007 si creano dentro la transazione della migrazione e bloccano le scritture su <code>file_revisions</code> e <code>files</code> per la durata. Va bene alle dimensioni attuali; su un&#39;installazione molto grande servirebbe una migrazione <code>NO TRANSACTION</code> con <code>CREATE INDEX CONCURRENTLY</code>.</li><li><strong>Connessioni:</strong> il pool degli advisory lock aggiunge fino a 5 connessioni PostgreSQL per replica del worker. È documentato nella guida di amministrazione.</li></ul>',11)])])}const v=o(t,[["render",c]]);export{u as __pageData,v as default};
